// CloudIT Operations Portal — Phase 4 evidence publishing (Phase 0 spec section 7).
//
// Input (from the calling workflow):
//   records      array of sanitized envelope objects (contractVersion 1.0)
//   publisherKey publisher key; defaults to the Cavetta production publisher
//
// The publisher secret is read from the n8n container environment. The same
// value is stored (salted-hashed) in the operations database and in the
// operations-ingest service configuration; it is never written to any Data
// Table or execution payload.

const crypto = require('crypto');

const input = $input.first().json;
const publisherKey = input.publisherKey || 'cavetta-production-n8n';
const envName = 'OPERATIONS_PUBLISHER_SECRET_' + publisherKey.toUpperCase().replace(/[^A-Z0-9]+/g, '_');
const secret = $env[envName];
if (!secret) {
  throw new Error('publisher secret environment variable missing: ' + envName);
}

const records = input.records;
if (!Array.isArray(records) || records.length === 0) {
  throw new Error('records must be a non-empty array');
}
if (records.length > 500) {
  throw new Error('batch too large: ' + records.length + ' records (max 500)');
}

const bodyText = JSON.stringify(records);
if (Buffer.byteLength(bodyText, 'utf8') > 1048576) {
  throw new Error('batch too large: over 1 MiB');
}

const timestamp = Math.floor(Date.now() / 1000).toString();
const nonce = crypto.randomBytes(16).toString('base64url');
const digest = crypto.createHash('sha256').update(bodyText, 'utf8').digest('hex');
const signature = crypto.createHmac('sha256', secret)
  .update(timestamp + '.' + nonce + '.' + digest)
  .digest('hex');

return [{
  json: {
    bodyText,
    publisherKey,
    timestamp,
    nonce,
    signature
  }
}];

// Treat only accepted / duplicate_batch as success so the caller's
// error handling sees every rejection or transport failure.
const r = $input.first().json;
if (r.result !== 'accepted' && r.result !== 'duplicate_batch') {
  throw new Error('operations ingest rejected the batch: ' + (r.code || r.result || 'unknown'));
}
return $input.all();
